BEGIN;
SET application_name TO E'a\047b';
SHOW application_name;
SET application_name TO $$dollar'quote$$;
SHOW application_name;
SET application_name TO 'doubled''quote';
SHOW application_name;
SET application_name TO E'a\tb';
SHOW application_name;
SET application_name TO $$DEFAULT$$;
SHOW application_name;
SET application_name TO +1;
SHOW application_name;
SET search_path TO E'Case\tName',public;
SHOW search_path;
SET search_path TO E'quote\047name',$$dollar,name$$,"Mixed Case";
SHOW search_path;
SET DateStyle TO ISO,DMY;
SHOW DateStyle;
RESET search_path;
SET application_name TO 'outside';
CREATE FUNCTION public.decoded_sql_setting() RETURNS text LANGUAGE sql SET application_name TO E'function\047value' AS $$SELECT current_setting('application_name')$$;
SELECT public.decoded_sql_setting(),current_setting('application_name');
ALTER FUNCTION public.decoded_sql_setting() SET application_name TO $$changed'value$$;
SELECT public.decoded_sql_setting(),current_setting('application_name');
ALTER FUNCTION public.decoded_sql_setting() SET application_name TO DEFAULT;
SELECT public.decoded_sql_setting(),proconfig IS NULL FROM pg_proc WHERE proname='decoded_sql_setting';
CREATE FUNCTION public.decoded_sql_default() RETURNS text LANGUAGE sql SET application_name TO DEFAULT AS $$SELECT current_setting('application_name')$$;
SELECT public.decoded_sql_default(),proconfig IS NULL FROM pg_proc WHERE proname='decoded_sql_default';
ALTER FUNCTION public.decoded_sql_default() SET application_name TO 'DEFAULT';
SELECT public.decoded_sql_default();
ALTER ROLE postgres SET application_name TO E'role\047value';
SELECT setconfig[1] FROM pg_db_role_setting WHERE setrole='postgres'::regrole AND setdatabase=0;
ALTER ROLE postgres RESET application_name;
ALTER DATABASE postgres SET application_name TO $$database'value$$;
SELECT setconfig[1] FROM pg_db_role_setting WHERE setrole=0 AND setdatabase=(SELECT oid FROM pg_database WHERE datname='postgres');
ALTER DATABASE postgres RESET application_name;
SET TIME ZONE $$UTC$$;
SHOW timezone;
SET TIME ZONE 2;
SHOW timezone;
SET timezone TO +2;
SHOW timezone;
SET TIME ZONE '2';
SHOW timezone;
SET TIME ZONE '-2';
SHOW timezone;
SELECT set_config('timezone','2.5',false);
SELECT extract(timezone FROM timestamptz '2000-01-01 00:00+00');
SET TIME ZONE '+02:00';
SHOW timezone;
SELECT extract(timezone FROM timestamptz '2000-01-01 00:00+00');
CREATE FUNCTION public.decoded_timezone_setting() RETURNS text LANGUAGE sql SET timezone TO '2.5' AS $$SELECT current_setting('timezone')$$;
SELECT public.decoded_timezone_setting();
DROP FUNCTION public.decoded_timezone_setting();
DROP FUNCTION public.decoded_sql_setting();
DROP FUNCTION public.decoded_sql_default();
RESET ALL;
COMMIT;
